public static TFMPageMenuItemsFormHelper Construct(FormDataSource _ds)
{
    return new TFMPageMenuItemsFormHelper(_ds);
}

protected void new(FormDataSource _ds)
{
    ds = _ds;
    QueryBuildDataSource qbds = ds.queryBuildDataSource();
    qbr = qbds.addRange(fieldNum(TFMPageMenuItems,PageID ));
}

public TFMPageID latestID()
{
    return prevsender != null ? strReplace(prevsender.name(),'_MenuItem_','') : '';
}

