public static Map getPageMenuItemStateConfigurations(str _pageName, TFMPages _pages = TFMPagesProvider::getAllPages())
{
    TFMPageMenuItems	menuItemsTable;
    Map					foundPages;
    TFMPage				page;
    Map					actions = new Map (Types::String, Types::Class); //menuItems
    MapEnumerator		mEnum;
    TFMMenuItemStateConfiguration menuItem;
    MapEnumerator		pageEnum;

    if (!_pageName)
    {
        return actions;
    }

    page = _pages.getPage(_pageName);
    actions = page.getPageActions() == null ? actions : page.getPageActions();

    while select menuItemsTable where menuItemsTable.PageID == _pageName
    {
        if(!menuItemsTable.Hide && (!page.getConfiguration() || ((page.getConfiguration().isOfflineEnabled() && menuItemsTable.MenuItemType == TFMPageMenuItemTypes::OfflinePageMenuItem)) || (menuItemsTable.MenuItemType != TFMPageMenuItemTypes::OfflinePageMenuItem))) // Do not add the menu state configuration and skipif is hidden and skip offline menu items if the page is not in offline mode.
        {
            menuItem = TFMMenuItemStateConfiguration::Construct(menuItemsTable.MenuPageID, !menuItemsTable.PromotedItem ? -1 : menuItemsTable.LineNumber);
            menuItem.parmEnabled(true);
            menuItem.parmIcon(menuItemsTable.Icon);
            menuItem.parmTitle(menuItemsTable.Title);
            actions.insert(menuItem.parmMenuItemName(),menuItem);
        }
    }		
    return actions;

}

public static str getMenuItemTitleStr(TFMPageMenuItems _record, TFMPages _pages)
{
    str imgStr;
    TFMPage page;

    if(_record.Title)
    {
        imgStr = _record.Title;
    }
    else
    {
        page = _pages.getPage(_record.MenuPageID);
        if(page != null)
        {
            imgStr = page.parmTitle();
        }
        else
        {
            imgStr = _record.MenuPageID;
        }
    }
    return imgStr;
}

public static str getMenuItemIconStr(TFMPageMenuItems _record, TFMPages _pages)
{
    str imgStr;
    TFMPage page;

    if(_record.Icon)
    {
        imgStr = _record.Icon;
    }
    else
    {
        page = _pages.getPage(_record.MenuPageID);
        if(page != null)
        {
            imgStr = page.parmIcon();
        }
        else
        {
            imgStr = _record.MenuPageID;
        }
    }
    return imgStr;
}

public void windowClickOverride(FormWindowControl _sender)
{

    if (prevsender != null)
    {
        prevsender.heightValue(75);
        prevsender.widthValue(75);
    }
    _sender.heightValue(95);
    _sender.widthValue(95);

    qbr.value(strReplace(_sender.name(),'_MenuItem_',''));
    ds.executeQuery();

    prevsender = _sender;
}
